INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('729b89f8-2662-40cb-a616-35173b87f72c', '21feff02-016d-46e2-bb9d-c27495133b1b', '85. óra: Projektóra', 'Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "25513a09-3676-4a7b-9a34-604e011b748d", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "bab7e54c-177c-4ede-aeb6-4ef2a0b844e0", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "763bcbbe-bdc4-4985-a466-8b2d6dcda4bd", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "39fcee8a-ea3a-43d7-a2af-ac73346d6aa0", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "8ab6dbf9-9f57-4364-a86f-85434d7c90ee", "text": "Igaz", "isCorrect": true}, {"id": "c5863d39-e3b7-46e9-837b-4ba935b45fbb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "accff16a-fb4b-4934-b4d4-2c06f965f812", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "d49f3485-ee01-4bd2-a0b2-3d8ef043a3ca", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "226971c5-bfd7-4998-a586-f8ae28bbd05a", "text": "Igaz", "isCorrect": true}, {"id": "e11d071c-3feb-4951-98b8-b77370e5f552", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "10c5b21b-1683-4325-a8da-05c3c293ca77", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "cd5126a3-54e5-408c-8534-c2dcbce6d530", "text": "Igaz", "isCorrect": true}, {"id": "00600823-663f-4dbf-bb62-699d57438d82", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('6654b2db-4b48-4908-a614-449e5f282a52', '21feff02-016d-46e2-bb9d-c27495133b1b', '86. óra: Nyitott mondatok', 'Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "f7e6fc9f-b3c5-413b-94cf-762f777335a8", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "02f474fd-5e4b-4ea0-bc5a-4841d7a4ea98", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "29497f26-b61a-4147-9eb4-e2f05deecb11", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "13063127-2f97-4196-b0c3-eccbd2797a40", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "85c888b9-23c9-4351-9594-22ce816607bb", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "b06f81d8-eb33-4094-9597-a4878ea37b14", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "cdac3156-48b9-4333-b7b9-0e5e597f09dc", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "5640b803-454a-4ddf-b58c-d15aa645a874", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "ab91724d-5220-4d07-b703-769018a7bd9f", "text": "Igaz", "isCorrect": true}, {"id": "daa3d474-f1c8-4933-a70a-cceecd386913", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8b888d0d-8a05-4ff7-a5ab-e85288079f56", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "14282246-a083-41d9-adb4-bf196f607e48", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "9b439ff7-3263-47e9-987a-17a749520e05", "text": "Igaz", "isCorrect": true}, {"id": "c8e61002-55f6-489c-95c7-00e652f37e43", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9c84b513-6541-4bb3-b1d1-c0191ec37418", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()),
('112b140e-afbe-4cc0-84db-83a5bb72b05a', '21feff02-016d-46e2-bb9d-c27495133b1b', '87. óra: Feladatmegoldás: Nyitott mondatok', 'Gyakorlás: lebontogatási módszer alkalmazása egyenletek és egyenlőtlenségek megoldásában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b05cabae-73a4-435c-b27a-93d0f73b0418", "text": "Melyik szám teszi igazzá: 4 * (x + 2) = 36? (36/4 = 9, 9-2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "a71422fe-7944-4def-bffc-9362785dc7ee", "text": "Melyik szám teszi igazzá: 5 * y - 12 = 38? (50/5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "34d90653-9153-4950-a744-19315f784ad1", "text": "Ha az alaphalmaz a természetes számok (0, 1, 2, ...), hány megoldása van a 2 * x < 6 egyenlőtlenségnek? (x = 0, 1, 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "a212cf36-4ff1-4bc5-93a4-44ae3752f59c", "text": "Az egyenlőtlenségeknek több megoldása is lehet egy megadott alaphalmazon.", "type": "true-false", "options": [{"id": "85617496-5e65-4e88-a3a4-89974ba34d2b", "text": "Igaz", "isCorrect": true}, {"id": "d2eadfc9-2bde-4c1c-9455-130ea4a612d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4b6aa7aa-2b26-4ad2-aaec-aacb416643d0", "text": "Melyik szám teszi igazzá: (z + 10) / 2 = 15?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "f676e68b-e9a7-4c3f-ba0a-55d57036118c", "text": "Ha az egyenletnek nincs megoldása az adott alaphalmazon, az igazsághalmaz az üres halmaz.", "type": "true-false", "options": [{"id": "6f2fcfd5-bf67-4329-ac38-c92de7a7c0b3", "text": "Igaz", "isCorrect": true}, {"id": "23e6fa15-8982-4e07-b42c-6851c768b31f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "06a50e78-193c-4277-9cf9-ec26b987b0d9", "text": "Melyik szám teszi igazzá: 10 * x - 25 = 75?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('720be285-52fa-40fc-a52a-21d600ade74b', '21feff02-016d-46e2-bb9d-c27495133b1b', '88. óra: Gyakorlóóra', 'Nyitott mondatok és műveleti sorrend gyakorlása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "5e4f3d44-68bc-4b19-82ca-ef00db525b96", "text": "Melyik szám teszi igazzá: 3 * x + 7 = 34?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "00012f09-dd4b-4e0c-ac87-f28d49bf0838", "text": "Melyik szám teszi igazzá: (x - 5) * 6 = 42?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "c8a13677-786e-4bea-9cbe-392cc41df0d5", "text": "A lebontogatás lépései során az utolsóként elvégzett művelet inverzével kezdjük a számolást.", "type": "true-false", "options": [{"id": "ab8ce67e-6c0d-4180-95a1-1117e6ef439b", "text": "Igaz", "isCorrect": true}, {"id": "bb0bc5f5-8c99-44d7-bc86-ddddc30b5292", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1703fce6-d6e2-440e-a269-54a6233e9132", "text": "Mennyi x értéke, ha 50 - 2 * x = 30? (2x = 20)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "dab24287-2b65-44dc-8f5d-41a9bf19e7b7", "text": "Mennyi y értéke, ha y / 3 - 4 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "f9a54dd4-6a42-46be-bb5f-2a219f245277", "text": "Az ellenőrzés kihagyása növeli a hibázás kockázatát.", "type": "true-false", "options": [{"id": "48bf1e55-9b2b-4883-a1c7-34de0d40b705", "text": "Igaz", "isCorrect": true}, {"id": "9548f6e3-3fc7-414f-aa8d-a1f22cd25a65", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cec07483-55a6-4ef7-a23c-45a8571bdffa", "text": "Melyik szám teszi igazzá: 8 * a + 4 = 68?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()),
('77ba5457-4d34-4a84-b40c-d55d383553a6', '21feff02-016d-46e2-bb9d-c27495133b1b', '89. óra: Szöveges feladatok', 'Szöveges feladatok megoldása nyitott mondatok felírásával, ábrakészítéssel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "52f57411-e459-4618-9b30-b87d97778e61", "text": "Gondoltam egy számot, megszóroztam 3-mal, hozzáadtam 12-őt és 45-öt kaptam. Mi volt a szám? (3x + 12 = 45 -> 3x = 33)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "99d14b7b-66e1-452d-8d61-993a5db47461", "text": "Gondoltam egy számot, kivontam belőle 8-at, megszoroztam 4-gyel és 40-et kaptam. Mi volt a szám? ((x-8)*4 = 40 -> x-8 = 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "9aee4128-b30f-492c-b309-8767a8a1be14", "text": "Katinak 3-szor annyi matricája van, mint Petinek. Összesen 48 matricájuk van. Hány matricája van Petinek? (x + 3x = 48 -> 4x = 48)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "ae62919e-4ca9-47a7-b007-2f2dfe283d1e", "text": "Hány matricája van Katinak? (3 * 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "b081c2c3-a8a4-4c3c-9e64-8e1d28feff09", "text": "A szöveges feladatok megoldásának lépései: Értelmezés -> Adatok/Ismeretlen -> Nyitott mondat -> Számolás -> Ellenőrzés -> Válaszmondat.", "type": "true-false", "options": [{"id": "8ad506d6-db8a-472d-9916-a60809e5b94b", "text": "Igaz", "isCorrect": true}, {"id": "877724e5-cf34-49e2-8ff6-fa1270445617", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d80d8b9d-b94f-4ed3-9dd1-6750b280a5a5", "text": "Ha a feladatban a ''kétszer annyi'' kifejezés szerepel, 2-vel való szorzásra gondolunk.", "type": "true-false", "options": [{"id": "f902b11e-a492-421a-aac0-ee8aee2db188", "text": "Igaz", "isCorrect": true}, {"id": "488cf546-a657-4356-acc1-8f575ee27d44", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5d5a836b-a785-4a8c-aa47-7bcc7a8b4804", "text": "Gondoltam egy számot, elosztottam 5-tel, hozzáadtam 7-et és 12-őt kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW());